(() => {
  const g = window.gerard;
  window.plan = n => g.story.place('castillo-' + n).palace.floor;
  window.enter = n => { const f = window.plan(n), p = f.puzzle, r = f.rooms[p.room]; window.__f = f; window.__p = p; window.__r = r; g.story.fears('castillo-' + n); g.story.castle.beaten = { ...g.story.castle.beaten, [n]: f.rooms.map(room => room.id) }; g.game.setEnvironment('castillo-' + n, { ...p.entry }); };
  window.offset = () => { const at = g.game.app.root.findByName('Jugador').getPosition(), p = window.__p; window.__o = { x: at.x - p.entry.x, z: at.z - p.entry.z }; };
  window.look = (cell, d, y) => g.game.frame({ x: cell.x + window.__o.x, y: y ?? .8, z: cell.z + window.__o.z }, d);
  // The two keys that walk a grid step with the camera at home (src/movement.ts screenToGrid): +x right and down, -z right and up.
  window.keysFor = s => s.x > 0 ? ['ArrowRight', 'ArrowDown'] : s.x < 0 ? ['ArrowLeft', 'ArrowUp'] : s.z < 0 ? ['ArrowRight', 'ArrowUp'] : ['ArrowLeft', 'ArrowDown'];
  window.key = (type, code) => window.dispatchEvent(new KeyboardEvent(type, { code, key: code, bubbles: true }));
  window.walk = on => { for (const code of window.keysFor(window.__p.out)) window.key(on ? 'keydown' : 'keyup', code); };
  // Walks towards the door only while it is not looking: what a player who has understood it does.
  window.cross = () => { window.crossing = setInterval(() => { const d = g.game.door; window.walk(!!d && d.phase === 'away'); if (!d || !d.shut) { clearInterval(window.crossing); window.walk(false); } }, 30); };
})()
